import ast
src = open('grokking_optimizers/dispatch.py').read()
tree = ast.parse(src)
want = {'_FUSED_L3_REAL','_L3_WGMMA_CELLS'}
from collections import Counter
for node in ast.walk(tree):
    if isinstance(node, ast.Assign):
        for t in node.targets:
            if isinstance(t, ast.Name) and t.id in want:
                call = node.value  # ast.Call frozenset({...})
                setlit = call.args[0]
                val = ast.literal_eval(setlit)
                s = set(val)
                print(t.id, 'UNIQUE COUNT =', len(s))
                c = Counter(m for (m,o) in s)
                print('  by model:', dict(c))
                for x in sorted(s): print('   ', x)
                print()
"

